registerWindow(win) {
  if (registeredWindows.has(win)) {
    console.error(
      "Trying to register the same window twice",
      win.location.pathname
    );
    return;
  }

registeredWindows.add(win);
win.addEventListener(
  "unload",
  () => {
    registeredWindows.delete(win);
  },
  { once: true }
);
this.updateWindow(win);
